GLContext* currentContextOrNull() {
    return Runtime::shared().currentContext();
}

void setCurrentFloatAttrib(GLuint index, GLdouble x, GLdouble y,
                           GLdouble z, GLdouble w, GLint count) {
    auto* context = currentContextOrNull();
    if (context == nullptr) return;
    const GLdouble values[4] = {x, y, z, w};
    context->setVertexAttribImmediate(index, count, values);
}

void setCurrentIntAttrib(GLuint index, GLint x, GLint y, GLint z, GLint w) {
    auto* context = currentContextOrNull();
    if (context == nullptr) return;
    const GLint values[4] = {x, y, z, w};
    context->setVertexAttribIImmediate(index, values, false);
}

void setCurrentUIntAttrib(GLuint index, GLuint x, GLuint y, GLuint z, GLuint w) {
    auto* context = currentContextOrNull();
    if (context == nullptr) return;
    const GLint values[4] = {
        static_cast<GLint>(x),
        static_cast<GLint>(y),
        static_cast<GLint>(z),
        static_cast<GLint>(w),
    };
    context->setVertexAttribIImmediate(index, values, true);
}

GLint bufferTextureBytesPerTexel(GLenum fmt) {
    switch (fmt) {
        case GL_R8: case GL_R8I: case GL_R8UI:
            return 1;
        case GL_R16: case GL_R16I: case GL_R16UI: case GL_R16F:
        case GL_RG8: case GL_RG8I: case GL_RG8UI:
            return 2;
        case GL_R32I: case GL_R32UI: case GL_R32F:
        case GL_RG16: case GL_RG16I: case GL_RG16UI: case GL_RG16F:
        case GL_RGBA8: case GL_RGBA8I: case GL_RGBA8UI:
            return 4;
        case GL_RG32I: case GL_RG32UI: case GL_RG32F:
        case GL_RGBA16: case GL_RGBA16I: case GL_RGBA16UI: case GL_RGBA16F:
            return 8;
        case GL_RGB32I: case GL_RGB32UI: case GL_RGB32F:
            return 12;
        case GL_RGBA32I: case GL_RGBA32UI: case GL_RGBA32F:
            return 16;
        default:
            return 0;
    }
}

// Phase 8X Group 4d follow-up¹¹ — §Tertiary chokepoint-bypass
// warning helper. Many 3.3 texture-upload entry points in this file
// are still pass-through no-op stubs (`(void)data;`) from the
// original Phase A gate landing. If Recoil's glyph cache (or any
// other consumer) calls one of these, the byte payload is silently
// dropped, which is one of BAR's followup¹⁰ hypotheses for "where
// is the real glyph atlas going". Each stub that drops data now
// fires a one-shot stderr warning the first time it's invoked so
// BAR's log capture will show exactly which bypass is in use.
//
// Writes to stderr via fprintf because AppGLGroup8.cpp is plain C++
// and NSLog requires an Objective-C++ translation unit. NSLog's
// default destination on macOS is also stderr, so BAR's existing
// grep-for-[GL] pattern works uniformly across both paths.
void warnDataDroppedOnce(const char* functionName) {
    static std::unordered_set<std::string> warned;
    if (warned.insert(functionName).second) {
        std::fprintf(stderr,
                     "[GL] WARNING: %s called but the implementation is a"
                     " drop-data stub — texture byte payload is discarded."
                     " Phase 8X Group 4d follow-up¹¹ bypass instrumentation.\n",
                     functionName);
        std::fflush(stderr);
    }
}

