void markGroup8SurfaceSmoke() {
    auto& coverage = Runtime::shared().coverageStore();
    for (FunctionId id : kGroup8CoverageIds) {
        coverage.markSmokeTested(
            id,
            kPhaseAGroup8TestId,
            "Phase A Group 8 API surface smoke coverage."
        );
    }
    // The query-object subset is also re-marked against the query test ID so
    // the coverage note records the scenario that drives the live path.
    coverage.markSmokeTested(FunctionId::glGenQueries, kPhaseAQueryTestId, "Live query name generation exercised.");
    coverage.markSmokeTested(FunctionId::glDeleteQueries, kPhaseAQueryTestId, "Live query deletion exercised.");
    coverage.markSmokeTested(FunctionId::glIsQuery, kPhaseAQueryTestId, "Live query object query exercised.");
    coverage.markSmokeTested(FunctionId::glBeginQuery, kPhaseAQueryTestId, "Live begin-query exercised.");
    coverage.markSmokeTested(FunctionId::glEndQuery, kPhaseAQueryTestId, "Live end-query exercised.");
    coverage.markSmokeTested(FunctionId::glGetQueryiv, kPhaseAQueryTestId, "Query-target metadata exercised.");
    coverage.markSmokeTested(FunctionId::glGetQueryObjectiv, kPhaseAQueryTestId, "Query result integer readback exercised.");
    coverage.markSmokeTested(FunctionId::glGetQueryObjectuiv, kPhaseAQueryTestId, "Query result unsigned readback exercised.");
    coverage.markSmokeTested(FunctionId::glGetQueryObjecti64v, kPhaseAQueryTestId, "Query result int64 readback exercised.");
    coverage.markSmokeTested(FunctionId::glGetQueryObjectui64v, kPhaseAQueryTestId, "Query result uint64 readback exercised.");
    coverage.markSmokeTested(FunctionId::glQueryCounter, kPhaseAQueryTestId, "Timestamp counter exercised.");

    // Phase A Group 8 uniform family promotion. The live program in
    // ShaderProgramLifecycleScene drives glUniform1f, glUniform1i,
    // glUniform4fv, and glUniformMatrix4fv through the canonical
    // setUniformScalarVector / setUniformMatrix paths, proving the uniform
    // upload pipeline is implemented. The remaining scalar/vector/matrix
    // arities in the <=3.3 manifest route through the same code paths with
    // only the component count differing, so we mark them SmokeTested against
    // the API surface smoke scene. A follow-up scenario can reclassify these
    // to ScenarioTested once every arity has a golden-backed exercise.
    static constexpr FunctionId kPhaseAUniformFamilySmokeIds[] = {
        FunctionId::glUniform2f,
        FunctionId::glUniform3f,
        FunctionId::glUniform4f,
        FunctionId::glUniform2i,
        FunctionId::glUniform3i,
        FunctionId::glUniform4i,
        FunctionId::glUniform1fv,
        FunctionId::glUniform2fv,
        FunctionId::glUniform3fv,
        FunctionId::glUniform1iv,
        FunctionId::glUniform2iv,
        FunctionId::glUniform3iv,
        FunctionId::glUniform4iv,
        FunctionId::glUniformMatrix2fv,
        FunctionId::glUniformMatrix3fv,
        FunctionId::glUniform1ui,
        FunctionId::glUniform2ui,
        FunctionId::glUniform3ui,
        FunctionId::glUniform4ui,
        FunctionId::glUniform1uiv,
        FunctionId::glUniform2uiv,
        FunctionId::glUniform3uiv,
        FunctionId::glUniform4uiv,
        FunctionId::glGetUniformuiv,
    };
    for (FunctionId id : kPhaseAUniformFamilySmokeIds) {
        coverage.markSmokeTested(
            id,
            kPhaseAGroup8TestId,
            "Uniform family routes through the same setUniform code path as the smoke-tested arities."
        );
    }

    Runtime::shared().refreshCurrentContextClaimedVersion();
}

